import json
s=json.load(open('/tmp/seqs.json'))
def rc(x): return x.translate(str.maketrans('acgtACGT','tgcaTGCA'))[::-1]
out=s['output'].lower(); out2=out+out
K=25
idx={}
for i in range(len(out2)-K+1):
    idx.setdefault(out2[i:i+K],[]).append(i)
for k in ['input','egfp','flag','snap']:
    v=s[k].lower()
    for lab,q in (('+',v),('-',rc(v))):
        hits=[]
        for i in range(len(q)-K+1):
            for j in idx.get(q[i:i+K],[]):
                if j<len(out): hits.append((i,j))
        if not hits: 
            print(k,lab,'none'); continue
        # find contiguous blocks with j-i constant
        from collections import defaultdict
        d=defaultdict(list)
        for i,j in hits: d[j-i].append(i)
        for off,ii in d.items():
            print(k,lab,'offset',off,'query range',min(ii),max(ii)+K,'out range',min(ii)+off,max(ii)+K+off)
