cd /app && cat > check.py <<'EOF'
import json,subprocess
S={k:v.lower() for k,v in json.load(open('/tmp/seqs.json')).items()}
def rc(x): return x.translate(str.maketrans('acgt','tgca'))[::-1]
def tm(x):
    return float(subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',x.upper()],capture_output=True,text=True).stdout)
prim={}; name=None
for l in open('primers.fasta'):
    l=l.strip()
    if l.startswith('>'): name=l[1:]; prim[name]=''
    else: prim[name]+=l.lower()
res={}
for k,p in prim.items():
    t=S[k.split('_')[0]]; tt=t+t
    best=''
    for L in range(len(p),9,-1):
        if p[-L:] in tt: best=p[-L:]; break
    res[k]=(len(best),tm(best),best)
    print(k,'maxsuffix_len',len(best),'Tm',round(tm(best),2))
for f in ['input','egfp','flag','snap']:
    d=abs(res[f+'_fwd'][1]-res[f+'_rev'][1]); print(f,'dTm',round(d,2),'ok',d<=5 and all(58<=res[f+x][1]<=72 and 15<=res[f+x][0]<=45 for x in ['_fwd','_rev']))
print('blank lines:', any(l.strip()=='' for l in open('primers.fasta')))
EOF
